/**
 * Where uploaded document bytes live. The database only keeps the key, size
 * and SHA-256; production should use S3 / Drive with server-side encryption.
 */

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";

export interface FileStore {
  put(key: string, bytes: Buffer, mimeType: string): Promise<void>;
  get(key: string): Promise<Buffer>;
}

/** Keys are generated by the server, but stay inside rootDir regardless. */
export class LocalDiskStore implements FileStore {
  private readonly root: string;

  constructor(rootDir: string) {
    this.root = resolve(rootDir);
  }

  private pathFor(key: string): string {
    const full = resolve(join(this.root, key));
    if (!full.startsWith(this.root + sep)) throw new Error(`Storage key escapes the upload directory: ${key}`);
    return full;
  }

  async put(key: string, bytes: Buffer): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, bytes, { flag: "wx" }); // never overwrite an existing version
  }

  get(key: string): Promise<Buffer> {
    return readFile(this.pathFor(key));
  }
}

/** For tests. */
export class MemoryStore implements FileStore {
  readonly files = new Map<string, Buffer>();

  async put(key: string, bytes: Buffer): Promise<void> {
    if (this.files.has(key)) throw new Error(`Key already exists: ${key}`);
    this.files.set(key, bytes);
  }

  async get(key: string): Promise<Buffer> {
    const bytes = this.files.get(key);
    if (!bytes) throw new Error(`No file at ${key}`);
    return bytes;
  }
}

// ── Upload checks ────────────────────────────────────────────────────────────

export const MAX_UPLOAD_BYTES = 25 * 1024 * 1024;

const EXTENSIONS: Record<string, string> = {
  "application/pdf": ".pdf",
  "image/jpeg": ".jpg",
  "image/png": ".png",
  "image/heic": ".heic",
};

export const ALLOWED_MIME_TYPES = Object.keys(EXTENSIONS);

export function extensionFor(mimeType: string): string {
  return EXTENSIONS[mimeType] ?? "";
}

/** Checks the file's first bytes match its claimed type, so a renamed .exe isn't accepted as a PDF. */
export function contentMatchesMime(bytes: Buffer, mimeType: string): boolean {
  switch (mimeType) {
    case "application/pdf":
      return bytes.subarray(0, 5).toString("latin1") === "%PDF-";
    case "image/jpeg":
      return bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff;
    case "image/png":
      return bytes.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
    case "image/heic":
      return bytes.subarray(4, 8).toString("latin1") === "ftyp";
    default:
      return false;
  }
}
